    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
const body = $input.first().json.body || {};
const toolCall = (body.message && body.message.toolCalls && body.message.toolCalls[0]) || null;
const args = toolCall ? (toolCall.function.arguments || {}) : body;
const toolCallId = (toolCall && toolCall.id) || args.tool_call_id || genUUID();
const callId = args.call_id || args.session_id || args.conversation_id || args.call_sid || body.call_id || body.session_id || body.call_sid || null;
return [{ json: { ...args, call_id: callId, tool_call_id: toolCallId } }];

const action = $('manageCart: Apply Action').first().json;
const cartRow = $input.all()[0] ? $input.all()[0].json : null;

if (!action.order_found || Number(action.order_found) === 0) {
  return [{ json: { success: false, error_code: 'NO_ORDER_CONTEXT', message: 'No active order found for this call. Branch may not be resolved yet — call getHours or getMenu first.' } }];
}

const parsed = $('manageCart: Parse Input').first().json;
if (parsed.action === 'add' && Number(action.item_valid) === 0) {
  return [{ json: { success: false, error_code: 'ITEM_UNAVAILABLE', message: 'That item is not available at this branch.' } }];
}

return [{ json: { success: true, cart: cartRow ? { items: cartRow.items, subtotal: cartRow.subtotal, tax_total: cartRow.tax_total, total: cartRow.total } : { items: [], subtotal: 0, tax_total: 0, total: 0 } } }];

const err = $json.error || {};
const msg = err.message || '';

if (msg.includes('invalid input syntax for type uuid')) {
  return [{ json: {
    success: false,
    error_code: 'INVALID_ITEM_ID',
    message: 'I didn\'t get a valid item reference for that — could you tell me the item name again so I can look it up?'
  } }];
}

return [{ json: { success: false, error_code: err.code || 'DB_ERROR', message: err.message || 'Could not update the cart.' } }];

const parsed = $('manageCart: Parse Input').first().json;
